pi = {'N': 0.6, 'V': 0.4}
A = {('N','N'): 0.4, ('N','V'): 0.6, ('V','N'): 0.7, ('V','V'): 0.3}
B = {('N','fish'): 0.5, ('V','fish'): 0.2, ('N','sleep'): 0.1, ('V','sleep'): 0.6}
words = ['fish', 'sleep']
delta1 = {j: pi[j] * B[(j, words[0])] for j in 'NV'}
print(round(delta1['N'], 4))
print(round(delta1['V'], 4))
delta2 = {}
for j in 'NV':
    best = max(delta1[i] * A[(i, j)] for i in 'NV')
    delta2[j] = best * B[(j, words[1])]
print(round(delta2['N'], 4))
print(round(delta2['V'], 4))
